    private final Handler handler=new Handler(Looper.getMainLooper());
    private SharedPreferences prefs;private Updater updater;private ThumbnailCache thumbs;private FrameLayout root,content,nav,viewer;private LinearLayout header,navButtons;private TextView title,subtitle,pager;private Button previous,next;private HoneycombView gallery;private GlassBar glass;private ScrollView collections;private VideoView video;
    private List<Media> all=new ArrayList<>(),shown=new ArrayList<>(),viewList=new ArrayList<>();private final Set<String> favorites=new HashSet<>(),selected=new HashSet<>();private final Map<String,float[]> positions=new HashMap<>();
    private final String[] tabs={"Pictures","Albums","Stories","Favourites"};private int layoutMode=0;private int tab=0,viewIndex=0,loadGeneration=0,viewerGeneration=0;private String album="",query="";private boolean light=false,selecting=false,motion=true,permissionAsked=false,checked=false,loaded=false,collectionMode=false,initializing=true;
    private float focus=1,bounce=.66f,gap=4,radius=5,stagger=22,duration=520;private ContentObserver observer;
    private int bg(){return light?0xfff8f8fa:Color.BLACK;}private int fg(){return light?0xff17171a:Color.WHITE;}private int muted(){return light?0xff6c6c72:0xff96969e;}private int dp(float v){return Math.round(v*getResources().getDisplayMetrics().density);}
    @Override public void onCreate(Bundle saved){super.onCreate(saved);prefs=getSharedPreferences("hive",MODE_PRIVATE);favorites.addAll(prefs.getStringSet("favorites",Collections.emptySet()));light=prefs.getBoolean("light",false);layoutMode=prefs.getInt("layout_mode",0);if(layoutMode<0||layoutMode>2)layoutMode=0;motion=prefs.getBoolean("motion",true);focus=prefs.getFloat("focus",1);bounce=prefs.getFloat("bounce",.66f);gap=prefs.getFloat("gap",4);radius=prefs.getFloat("radius",5);stagger=prefs.getFloat("stagger",22);duration=prefs.getFloat("duration",520);thumbs=new ThumbnailCache(this);updater=new Updater(this);buildUi();initializing=false;
        observer=new ContentObserver(handler){@Override public void onChange(boolean selfChange){handler.removeCallbacks(refreshTask);handler.postDelayed(refreshTask,350);}};
        try{getContentResolver().registerContentObserver(MediaStore.Images.Media.EXTERNAL_CONTENT_URI,true,observer);getContentResolver().registerContentObserver(MediaStore.Video.Media.EXTERNAL_CONTENT_URI,true,observer);}catch(Exception ignored){}
        if(!hasAccess()){permissionAsked=true;requestMedia();}
    }
    private final Runnable refreshTask=()->{if(!isFinishing()&&!isDestroyed())loadMedia(false);};
    @Override protected void onResume(){super.onResume();if(gallery==null)return;if(hasAccess()||permissionAsked)loadMedia(!loaded);}
    @Override protected void onPause(){super.onPause();if(video!=null&&video.isPlaying())video.pause();}
    private boolean has(String p){return checkSelfPermission(p)==PackageManager.PERMISSION_GRANTED;}
    private boolean hasAccess(){if(Build.VERSION.SDK_INT>=33)return has(Manifest.permission.READ_MEDIA_IMAGES)||has(Manifest.permission.READ_MEDIA_VIDEO)||(Build.VERSION.SDK_INT>=34&&has(Manifest.permission.READ_MEDIA_VISUAL_USER_SELECTED));return has(Manifest.permission.READ_EXTERNAL_STORAGE);}
    private void requestMedia(){String[] permissions=Build.VERSION.SDK_INT>=34?new String[]{Manifest.permission.READ_MEDIA_IMAGES,Manifest.permission.READ_MEDIA_VIDEO,Manifest.permission.READ_MEDIA_VISUAL_USER_SELECTED}:Build.VERSION.SDK_INT>=33?new String[]{Manifest.permission.READ_MEDIA_IMAGES,Manifest.permission.READ_MEDIA_VIDEO}:new String[]{Manifest.permission.READ_EXTERNAL_STORAGE};requestPermissions(permissions,MEDIA_PERMISSION);}
    @Override public void onRequestPermissionsResult(int req,String[] names,int[] grants){super.onRequestPermissionsResult(req,names,grants);if(req==MEDIA_PERMISSION){permissionAsked=true;thumbs.resetFailures();loadMedia(true);if(!hasAccess())toast("Photo access is limited. Change access from the menu.");}}
    @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==INSTALL_PERMISSION&&getPackageManager().canRequestPackageInstalls())updater.resumeInstall();}
    private void loadMedia(boolean animate){int generation=++loadGeneration;io.execute(()->{List<Media> result;try{result=Media.query(this);}catch(Exception e){result=Collections.emptyList();}List<Media> copy=result;runOnUiThread(()->{if(isDestroyed()||generation!=loadGeneration)return;boolean changed=!same(all,copy);all=copy;boolean first=!loaded;loaded=true;if(changed||first||animate){remember();render(animate||first);}});});}
    private boolean same(List<Media>a,List<Media>b){if(a.size()!=b.size())return false;for(int i=0;i<a.size();i++)if(!a.get(i).uri.equals(b.get(i).uri)||a.get(i).date!=b.get(i).date||!a.get(i).name.equals(b.get(i).name)||!a.get(i).album.equals(b.get(i).album))return false;return true;}
    private GradientDrawable round(int color,float r,int stroke){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(r));if(stroke!=0)d.setStroke(dp(1),stroke);return d;}
    private TextView text(String s,float sp,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(sp);t.setTextColor(color);t.setGravity(Gravity.CENTER_VERTICAL);if(bold)t.setTypeface(android.graphics.Typeface.create("sans-serif-medium",0));return t;}
    private Button button(String s,Runnable action){Button b=new Button(this);b.setText(s);b.setTextColor(fg());b.setTextSize(13);b.setAllCaps(false);b.setMinHeight(0);b.setMinimumHeight(0);b.setMinWidth(0);b.setMinimumWidth(0);b.setPadding(dp(9),0,dp(9),0);b.setBackground(round(light?0x09000000:0x15ffffff,22,light?0x18000000:0x25ffffff));b.setOnClickListener(v->action.run());return b;}
    private android.graphics.drawable.Drawable vector(int id,int size){android.graphics.drawable.Drawable d=getDrawable(id).mutate();d.setTint(fg());d.setBounds(0,0,dp(size),dp(size));return d;}
    private Button iconButton(int id,String label,Runnable action){Button b=button("",action);b.setPadding(0,0,0,0);b.setContentDescription(label);b.setCompoundDrawables(null,vector(id,20),null,null);b.setGravity(Gravity.CENTER);return b;}
    private void actionIcon(Button b,int id){b.setCompoundDrawables(null,vector(id,20),null,null);b.setCompoundDrawablePadding(dp(3));}
    private FrameLayout.LayoutParams frame(int w,int h,int gravity){return new FrameLayout.LayoutParams(w<0?w:dp(w),h<0?h:dp(h),gravity);}
    private LinearLayout vertical(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
    private LinearLayout horizontal(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.HORIZONTAL);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
    private void buildUi(){
        if(Build.VERSION.SDK_INT>=30)getWindow().setDecorFitsSystemWindows(false);else getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LAYOUT_STABLE|View.SYSTEM_UI_FLAG_LAYOUT_FULLSCREEN|View.SYSTEM_UI_FLAG_LAYOUT_HIDE_NAVIGATION);getWindow().setStatusBarColor(Color.TRANSPARENT);getWindow().setNavigationBarColor(Color.TRANSPARENT);if(Build.VERSION.SDK_INT>=29)getWindow().setNavigationBarContrastEnforced(false);
        root=new FrameLayout(this);root.setBackgroundColor(bg());root.setOnApplyWindowInsetsListener((v,in)->{if(Build.VERSION.SDK_INT>=30){android.graphics.Insets i=in.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());v.setPadding(i.left,i.top,i.right,i.bottom);}else v.setPadding(in.getSystemWindowInsetLeft(),in.getSystemWindowInsetTop(),in.getSystemWindowInsetRight(),in.getSystemWindowInsetBottom());return in;});setContentView(root);root.requestApplyInsets();
        content=new FrameLayout(this);FrameLayout.LayoutParams cp=frame(-1,-1,Gravity.TOP);cp.topMargin=dp(116);root.addView(content,cp);
        gallery=new HoneycombView(this,thumbs,this);content.addView(gallery,frame(-1,-1,Gravity.TOP));
        header=vertical();header.setPadding(dp(21),dp(9),dp(21),dp(6));root.addView(header,frame(-1,116,Gravity.TOP));
        nav=new FrameLayout(this);FrameLayout.LayoutParams np=frame(-1,71,Gravity.BOTTOM);np.leftMargin=np.rightMargin=dp(16);np.bottomMargin=dp(12);root.addView(nav,np);
        glass=new GlassBar(this,gallery);nav.addView(glass,frame(-1,-1,Gravity.TOP));navButtons=horizontal();navButtons.setPadding(dp(5),dp(5),dp(5),dp(5));nav.addView(navButtons,frame(-1,-1,Gravity.TOP));
        applyTheme();buildHeader();buildNav();gallery.settings(focus,bounce,gap,radius,stagger,duration,motion);glass.motion(motion);render(false);
    }
    private void applyTheme(){root.setBackgroundColor(bg());header.setBackgroundColor(bg());gallery.theme(light);glass.theme(light);if(Build.VERSION.SDK_INT>=30){WindowInsetsController ctl=getWindow().getInsetsController();if(ctl!=null)ctl.setSystemBarsAppearance(light?WindowInsetsController.APPEARANCE_LIGHT_STATUS_BARS|WindowInsetsController.APPEARANCE_LIGHT_NAVIGATION_BARS:0,WindowInsetsController.APPEARANCE_LIGHT_STATUS_BARS|WindowInsetsController.APPEARANCE_LIGHT_NAVIGATION_BARS);}else getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LAYOUT_STABLE|View.SYSTEM_UI_FLAG_LAYOUT_FULLSCREEN|View.SYSTEM_UI_FLAG_LAYOUT_HIDE_NAVIGATION|(light?(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR):0));}
    private void buildHeader(){header.removeAllViews();TextView brand=text("H I V E   /   G A L L E R Y",9,muted(),true);brand.setLetterSpacing(.10f);header.addView(brand,new LinearLayout.LayoutParams(-1,dp(18)));
        LinearLayout row=horizontal();header.addView(row,new LinearLayout.LayoutParams(-1,dp(50)));if(!album.isEmpty()||selecting||!query.isEmpty()){Button back=iconButton(R.drawable.ic_chevron_left,"Back",this::back);back.setContentDescription("Back");row.addView(back,new LinearLayout.LayoutParams(dp(39),dp(36)));}
        title=text("",34,fg(),true);title.setSingleLine(true);title.setEllipsize(android.text.TextUtils.TruncateAt.END);row.addView(title,new LinearLayout.LayoutParams(0,-1,1));
        Button search=iconButton(R.drawable.ic_search,"Search media",this::searchDialog);search.setContentDescription("Search media");search.setTextSize(22);row.addView(search,new LinearLayout.LayoutParams(dp(39),dp(36)));Button menu=iconButton(R.drawable.ic_more_horizontal,"Settings and actions",this::menu);menu.setContentDescription("Settings and actions");menu.setTextSize(22);LinearLayout.LayoutParams mp=new LinearLayout.LayoutParams(dp(39),dp(36));mp.leftMargin=dp(5);row.addView(menu,mp);
        LinearLayout sub=horizontal();header.addView(sub,new LinearLayout.LayoutParams(-1,dp(29)));subtitle=text("",11,muted(),false);subtitle.setSingleLine(true);subtitle.setEllipsize(android.text.TextUtils.TruncateAt.END);sub.addView(subtitle,new LinearLayout.LayoutParams(0,-1,1));
        previous=iconButton(R.drawable.ic_chevron_left,"Previous batch",()->gallery.movePage(-1));previous.setContentDescription("Previous media batch");sub.addView(previous,new LinearLayout.LayoutParams(dp(31),dp(25)));pager=text("",11,fg(),true);pager.setGravity(Gravity.CENTER);sub.addView(pager,new LinearLayout.LayoutParams(dp(47),-1));next=iconButton(R.drawable.ic_chevron_right,"Next batch",()->gallery.movePage(1));next.setContentDescription("Next media batch");sub.addView(next,new LinearLayout.LayoutParams(dp(31),dp(25)));updateHeader();
    }
    private void updateHeader(){if(title==null)return;title.setText(selecting?selected.size()+" selected":!album.isEmpty()?album:!query.isEmpty()?"Search":tabs[tab]);title.setTextSize(selecting?25:34);subtitle.setText(!query.isEmpty()?query+" · "+shown.size()+" items":collectionMode?"Your collections":!hasAccess()?"Allow access to photos and videos":!loaded?"Loading your library…":shown.size()+" media items");page(gallery.pageIndex(),gallery.pageCount());}
    private void buildNav(){navButtons.removeAllViews();String[] labels=selecting?new String[]{"Select all","Favourite","Done"}:tabs;for(int i=0;i<labels.length;i++){final int n=i;LinearLayout item=vertical();item.setGravity(Gravity.CENTER);item.setContentDescription(labels[i]);item.setFocusable(true);item.setClickable(true);item.setOnClickListener(v->{if(selecting){if(n==0){for(Media m:shown)selected.add(m.uri.toString());gallery.marks(favorites,selected,true);updateHeader();}else if(n==1){favorites.addAll(selected);saveFavorites();finishSelection();}else finishSelection();}else switchTab(n);});ImageView icon=new ImageView(this);icon.setImageDrawable(vector(selecting?new int[]{R.drawable.ic_check_square,R.drawable.ic_heart,R.drawable.ic_check}[i]:new int[]{R.drawable.ic_image,R.drawable.ic_folder,R.drawable.ic_film,R.drawable.ic_heart}[i],23));icon.setScaleType(ImageView.ScaleType.FIT_CENTER);item.addView(icon,new LinearLayout.LayoutParams(dp(23),dp(23)));TextView label=text(labels[i],10,fg(),i==tab);label.setGravity(Gravity.CENTER);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(18));lp.topMargin=dp(3);item.addView(label,lp);navButtons.addView(item,new LinearLayout.LayoutParams(0,-1,1));}markTabs(false);}
    private void markTabs(boolean animate){glass.tab(selecting?0:tab,selecting?3:4);for(int i=0;i<navButtons.getChildCount();i++){View item=navButtons.getChildAt(i);boolean active=selecting||i==tab;item.setAlpha(active?1f:.65f);item.setSelected(active);if(animate&&active&&motion&&ValueAnimator.areAnimatorsEnabled()){View icon=((LinearLayout)item).getChildAt(0);icon.animate().cancel();icon.setScaleX(.86f);icon.setScaleY(.86f);icon.animate().scaleX(1).scaleY(1).setDuration(400).setInterpolator(new android.view.animation.OvershootInterpolator(2f)).start();}}}
    private String stateKey(){return layoutMode+":"+tab+":"+album+":"+query;}
    private void remember(){if(!collectionMode&&gallery!=null)positions.put(stateKey(),new float[]{gallery.pageIndex(),gallery.scrollPosition()});}
    private boolean isCollections(){return (tab==1||tab==2)&&album.isEmpty()&&query.isEmpty();}
    private void switchTab(int i){if(i==tab&&album.isEmpty()&&query.isEmpty())return;remember();tab=i;album="";query="";buildHeader();markTabs(true);render(true);}
    private List<Media> filtered(){ArrayList<Media> list=new ArrayList<>();String q=query.toLowerCase(Locale.ROOT);for(Media m:all){if(tab==3&&!favorites.contains(m.uri.toString()))continue;if(!album.isEmpty()&&!m.album.equals(album))continue;if(!q.isEmpty()&&!(m.name+" "+m.album+" "+m.day+" "+m.displayDate("MMMM yyyy")).toLowerCase(Locale.ROOT).contains(q))continue;list.add(m);}if(layoutMode==2)list.sort(Comparator.comparing((Media m)->m.name,String.CASE_INSENSITIVE_ORDER).thenComparing(m->m.uri.toString()));return list;}
    private void render(boolean animate){shown=filtered();boolean was=collectionMode;collectionMode=isCollections();if(collectionMode){ScrollView old=collections;buildCollections(animate);glass.source(collections);if(old!=null){old.setEnabled(false);if(animate&&motion&&ValueAnimator.areAnimatorsEnabled())old.animate().alpha(0).scaleX(.96f).scaleY(.96f).setDuration(230).withEndAction(()->content.removeView(old)).start();else content.removeView(old);}gallery.animate().cancel();if(animate&&motion&&ValueAnimator.areAnimatorsEnabled()&&gallery.getVisibility()==View.VISIBLE)gallery.animate().alpha(0).setDuration(230).withEndAction(()->{if(collectionMode){gallery.setVisibility(View.INVISIBLE);gallery.setAlpha(1);}}).start();else gallery.setVisibility(View.INVISIBLE);glass.invalidate();}else{
            ScrollView old=collections;collections=null;glass.source(null);gallery.animate().cancel();gallery.setAlpha(1);gallery.setVisibility(View.VISIBLE);gallery.marks(favorites,selected,selecting);gallery.grouping(layoutMode==0);gallery.setMedia(shown,animate&&!was);float[] pos=positions.get(stateKey());if(pos!=null)gallery.restore((int)pos[0],pos[1]);if(animate&&was)gallery.replay();if(old!=null){old.setClickable(false);if(animate&&motion&&ValueAnimator.areAnimatorsEnabled())old.animate().alpha(0).scaleX(.96f).scaleY(.96f).setDuration(230).withEndAction(()->content.removeView(old)).start();else content.removeView(old);}}
        updateHeader();if(animate&&motion&&ValueAnimator.areAnimatorsEnabled()){title.animate().cancel();title.setAlpha(0);title.setTranslationY(dp(8));title.animate().alpha(1).translationY(0).setDuration(280).start();}}
    private void buildCollections(boolean animate){collections=new ScrollView(this);collections.setFillViewport(false);collections.setVerticalScrollBarEnabled(false);collections.setOnScrollChangeListener((v,x,y,ox,oy)->glass.invalidate());collections.setClipToPadding(false);LinearLayout list=vertical();list.setPadding(dp(20),dp(8),dp(20),dp(110));collections.addView(list,new ScrollView.LayoutParams(-1,-2));content.addView(collections,frame(-1,-1,Gravity.TOP));LinkedHashMap<String,List<Media>> groups=new LinkedHashMap<>();for(Media m:all)groups.computeIfAbsent(m.album,k->new ArrayList<>()).add(m);
        if(tab==2){LinkedHashMap<String,List<Media>> days=new LinkedHashMap<>();for(Media m:all)days.computeIfAbsent(m.day,k->new ArrayList<>()).add(m);int i=0;for(List<Media> media:days.values()){if(i>=40)break;Media cover=media.get(0);LinearLayout card=collectionCard(cover,cover.displayDate("d MMMM yyyy"),media.size()+" memories",()->{remember();query=cover.day;buildHeader();render(true);},true);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(16);list.addView(card,lp);animateCard(card,i++,animate);}}
        else{LinearLayout row=null;int i=0;for(Map.Entry<String,List<Media>> entry:groups.entrySet()){String name=entry.getKey();if(i%2==0){row=horizontal();row.setGravity(Gravity.TOP);list.addView(row,new LinearLayout.LayoutParams(-1,-2));}LinearLayout card=collectionCard(entry.getValue().get(0),name,entry.getValue().size()+" items",()->{remember();album=name;buildHeader();render(true);},false);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.setMargins(dp(4),0,dp(4),dp(19));row.addView(card,lp);animateCard(card,i++,animate);}if(i%2==1&&row!=null)row.addView(new View(this),new LinearLayout.LayoutParams(0,1,1));}
        if(list.getChildCount()==0){TextView t=text("No media available. Allow access from the menu.",14,muted(),false);list.addView(t);}}
    private LinearLayout collectionCard(Media cover,String label,String count,Runnable action,boolean story){LinearLayout card=vertical();card.setClickable(true);card.setFocusable(true);card.setContentDescription(label+", "+count);card.setOnClickListener(v->action.run());ImageView im=new ImageView(this);im.setScaleType(ImageView.ScaleType.CENTER_CROP);im.setBackground(round(0xff35373a,24,0));im.setClipToOutline(true);card.addView(im,new LinearLayout.LayoutParams(-1,dp(story?205:145)));Runnable update=()->handler.post(()->{if(!isDestroyed()){Bitmap b=thumbs.get(cover,()->{});if(b!=null)im.setImageBitmap(b);}});Bitmap b=thumbs.get(cover,update);if(b!=null)im.setImageBitmap(b);TextView t=text(label,16,fg(),true);t.setSingleLine(true);t.setEllipsize(android.text.TextUtils.TruncateAt.END);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(27));lp.topMargin=dp(6);card.addView(t,lp);card.addView(text(count,12,muted(),false),new LinearLayout.LayoutParams(-1,dp(20)));return card;}
    private void animateCard(View card,int i,boolean animate){if(!animate||!motion||!ValueAnimator.areAnimatorsEnabled())return;card.setAlpha(0);card.setScaleX(.78f);card.setScaleY(.78f);card.setTranslationY(dp(16));card.animate().alpha(1).scaleX(1).scaleY(1).translationY(0).setStartDelay(Math.min(330,(long)(i*stagger))).setDuration((long)duration).setInterpolator(new android.view.animation.OvershootInterpolator(.95f)).start();}
    @Override public void date(String s){if(layoutMode==0&&subtitle!=null&&!collectionMode&&!selecting&&query.isEmpty()&&!s.contentEquals(subtitle.getText()))subtitle.setText(s);}
    @Override public void page(int i,int count){if(pager==null)return;int visibility=!collectionMode&&count>1?View.VISIBLE:View.GONE;pager.setVisibility(visibility);previous.setVisibility(visibility);next.setVisibility(visibility);pager.setText((i+1)+" / "+count);previous.setEnabled(i>0);next.setEnabled(i+1<count);}
    @Override public void redrawGlass(){if(glass!=null)glass.invalidate();}
    @Override public void open(Media m){if(selecting){toggle(m);return;}showViewer(m);}
    @Override public void hold(Media m){if(!selecting){selecting=true;selected.clear();buildNav();}toggle(m);}
    private void toggle(Media m){String key=m.uri.toString();if(!selected.add(key))selected.remove(key);gallery.marks(favorites,selected,true);updateHeader();}
    private void finishSelection(){selecting=false;selected.clear();remember();buildNav();buildHeader();render(false);}
    private void saveFavorites(){prefs.edit().putStringSet("favorites",new HashSet<>(favorites)).apply();}
    private void searchDialog(){EditText input=new EditText(this);input.setSingleLine(true);input.setHint("Filename, album or date (YYYY-MM-DD)");input.setText(query);new AlertDialog.Builder(this).setTitle("Search media").setView(input).setNegativeButton("Cancel",null).setPositiveButton("Search",(d,w)->{remember();query=input.getText().toString().trim();album="";buildHeader();render(true);}).show();}
    private void menu(){String[] options={light?"Dark mode":"Light mode","Motion & appearance","Replay entry animation","Manage photo access","Accessible media list","About Hive","Gallery layout"};new AlertDialog.Builder(this).setTitle("Hive Gallery").setItems(options,(d,i)->{switch(i){case 0:light=!light;prefs.edit().putBoolean("light",light).apply();remember();applyTheme();buildHeader();buildNav();render(false);break;case 1:settings();break;case 2:if(collectionMode){remember();render(true);}else gallery.replay();break;case 3:requestMedia();break;case 4:accessibleList();break;case 5:new AlertDialog.Builder(this).setTitle("Hive Gallery "+BuildConfig.VERSION_NAME).setMessage("Native honeycomb gallery. Photos stay on your device.\n\nBuild "+BuildConfig.VERSION_CODE).setPositiveButton("OK",null).show();break;case 6:layoutDialog();break;}}).show();}
    private void layoutDialog(){String[] modes={"Chronological · day / month / year","Continuous · newest first, no date sections","Continuous · filename A–Z, no date sorting"};new AlertDialog.Builder(this).setTitle("Gallery layout").setSingleChoiceItems(modes,layoutMode,(dialog,i)->{if(i!=layoutMode){remember();layoutMode=i;prefs.edit().putInt("layout_mode",i).apply();render(true);}dialog.dismiss();}).setNegativeButton("Cancel",null).show();}
    private void accessibleList(){List<Media> list=shown;if(list.isEmpty()){toast("No media available");return;}int start=collectionMode?0:Math.min(gallery.firstVisibleIndex(),Math.max(0,list.size()-1));List<Media> sub=list.subList(start,Math.min(start+HoneycombView.PAGE_SIZE,list.size()));String[] labels=new String[sub.size()];for(int i=0;i<labels.length;i++)labels[i]=sub.get(i).name+" · "+sub.get(i).displayDate("d MMM yyyy");new AlertDialog.Builder(this).setTitle("Media in this batch").setItems(labels,(d,i)->open(sub.get(i))).setNegativeButton("Close",null).show();}
    interface FloatChange{void set(float v);}
    private void slider(LinearLayout l,String label,float value,int min,int max,FloatChange cb){TextView t=text(label+" · "+Math.round(value),14,fg(),false);l.addView(t);SeekBar s=new SeekBar(this);s.setMax(max-min);s.setProgress(Math.round(value)-min);l.addView(s);s.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}public void onProgressChanged(SeekBar b,int p,boolean from){float v=p+min;t.setText(label+" · "+Math.round(v));cb.set(v);applyMotion();}});}
    private void settings(){LinearLayout l=vertical();l.setPadding(dp(20),dp(10),dp(20),dp(10));CheckBox enabled=new CheckBox(this);enabled.setText("Screen animations");enabled.setChecked(motion);l.addView(enabled);enabled.setOnCheckedChangeListener((b,v)->{motion=v;applyMotion();});slider(l,"Focus strength (%)",focus*100,0,100,v->focus=v/100);slider(l,"Bounce intensity (%)",bounce*100,0,100,v->bounce=v/100);slider(l,"Media gap (dp)",gap,3,9,v->gap=v);slider(l,"Corner radius (dp)",radius,4,6,v->radius=v);slider(l,"Entry stagger (ms)",stagger,0,45,v->stagger=v);slider(l,"Entry duration (ms)",duration,250,850,v->duration=v);ScrollView s=new ScrollView(this);s.addView(l);new AlertDialog.Builder(this).setTitle("Motion & appearance").setView(s).setNeutralButton("Reset",(d,w)->{focus=1;bounce=.66f;gap=4;radius=5;stagger=22;duration=520;motion=true;applyMotion();gallery.replay();}).setPositiveButton("Done",(d,w)->{applyMotion();gallery.replay();}).show();}
    private void applyMotion(){gallery.settings(focus,bounce,gap,radius,stagger,duration,motion);glass.motion(motion);prefs.edit().putFloat("focus",focus).putFloat("bounce",bounce).putFloat("gap",gap).putFloat("radius",radius).putFloat("stagger",stagger).putFloat("duration",duration).putBoolean("motion",motion).apply();}
    private void showViewer(Media m){viewList=new ArrayList<>(shown);viewIndex=viewList.indexOf(m);if(viewIndex<0){viewList=new ArrayList<>(Collections.singletonList(m));viewIndex=0;}drawViewer(true);}
    private void drawViewer(boolean animate){if(viewList.isEmpty())return;Media m=viewList.get(viewIndex);if(video!=null){video.stopPlayback();video=null;}if(viewer!=null)root.removeView(viewer);int gen=++viewerGeneration;viewer=new FrameLayout(this);viewer.setBackgroundColor(bg());root.addView(viewer,frame(-1,-1,Gravity.TOP));LinearLayout wrap=vertical();viewer.addView(wrap,frame(-1,-1,Gravity.TOP));LinearLayout bar=horizontal();bar.setPadding(dp(15),dp(6),dp(15),dp(6));Button back=iconButton(R.drawable.ic_chevron_left,"Close media",this::closeViewer);back.setContentDescription("Close media");bar.addView(back,new LinearLayout.LayoutParams(dp(40),dp(40)));LinearLayout info=vertical();info.setGravity(Gravity.CENTER);TextView date=text(m.displayDate("d MMMM yyyy"),14,fg(),true);date.setGravity(Gravity.CENTER);info.addView(date);TextView name=text(m.name,11,muted(),false);name.setGravity(Gravity.CENTER);name.setSingleLine(true);name.setEllipsize(android.text.TextUtils.TruncateAt.END);info.addView(name);bar.addView(info,new LinearLayout.LayoutParams(0,-1,1));Button details=iconButton(R.drawable.ic_info,"Media details",()->details(m));details.setContentDescription("Media details");bar.addView(details,new LinearLayout.LayoutParams(dp(40),dp(40)));wrap.addView(bar,new LinearLayout.LayoutParams(-1,dp(58)));
        FrameLayout stage=new FrameLayout(this);wrap.addView(stage,new LinearLayout.LayoutParams(-1,0,1));if(m.video){video=new VideoView(this);stage.addView(video,frame(-1,-1,Gravity.CENTER));MediaController controller=new MediaController(this);video.setMediaController(controller);video.setVideoURI(m.uri);video.setOnPreparedListener(mp->video.seekTo(1));video.setOnErrorListener((mp,w,e)->{toast("Video could not be played");return true;});Button play=button("Play",()->{if(video!=null){video.start();}});actionIcon(play,R.drawable.ic_play);FrameLayout.LayoutParams pl=frame(94,60,Gravity.BOTTOM|Gravity.CENTER_HORIZONTAL);pl.bottomMargin=dp(12);stage.addView(play,pl);play.setOnClickListener(v->{if(video!=null){if(video.isPlaying()){video.pause();play.setText("Play");actionIcon(play,R.drawable.ic_play);}else{video.start();play.setText("Pause");actionIcon(play,R.drawable.ic_pause);}}});}else{ImageView image=new ImageView(this);image.setScaleType(ImageView.ScaleType.FIT_CENTER);stage.addView(image,frame(-1,-1,Gravity.CENTER));Bitmap b=thumbs.get(m,()->{});if(b!=null)image.setImageBitmap(b);viewerIO.execute(()->{try{Bitmap full=ImageDecoder.decodeBitmap(ImageDecoder.createSource(getContentResolver(),m.uri),(decoder,i,source)->{int w=i.getSize().getWidth(),h=i.getSize().getHeight();int target=Math.max(getResources().getDisplayMetrics().widthPixels,getResources().getDisplayMetrics().heightPixels);float f=Math.min(1f,target/(float)Math.max(w,h));decoder.setTargetSize(Math.max(1,(int)(w*f)),Math.max(1,(int)(h*f)));decoder.setAllocator(ImageDecoder.ALLOCATOR_SOFTWARE);});runOnUiThread(()->{if(gen==viewerGeneration&&!isDestroyed())image.setImageBitmap(full);});}catch(Exception e){runOnUiThread(()->{if(gen==viewerGeneration)toast("Unable to open image");});}});final float[] touch={0};image.setOnTouchListener((v,e)->{if(e.getAction()==MotionEvent.ACTION_DOWN){touch[0]=e.getX();return true;}if(e.getAction()==MotionEvent.ACTION_UP){float d=e.getX()-touch[0];if(Math.abs(d)>dp(45))stepViewer(d<0?1:-1);else v.performClick();return true;}return true;});}
        Button prev=iconButton(R.drawable.ic_chevron_left,"Previous media",()->stepViewer(-1)),next=iconButton(R.drawable.ic_chevron_right,"Next media",()->stepViewer(1));prev.setContentDescription("Previous media");next.setContentDescription("Next media");FrameLayout.LayoutParams a=frame(36,42,Gravity.CENTER_VERTICAL|Gravity.LEFT);a.leftMargin=dp(8);stage.addView(prev,a);FrameLayout.LayoutParams n=frame(36,42,Gravity.CENTER_VERTICAL|Gravity.RIGHT);n.rightMargin=dp(8);stage.addView(next,n);prev.setEnabled(viewIndex>0);next.setEnabled(viewIndex<viewList.size()-1);
        LinearLayout film=horizontal();film.setGravity(Gravity.CENTER);wrap.addView(film,new LinearLayout.LayoutParams(-1,dp(65)));for(int i=Math.max(0,viewIndex-3);i<=Math.min(viewList.size()-1,viewIndex+3);i++){final int idx=i;Media q=viewList.get(i);ImageView mini=new ImageView(this);mini.setScaleType(ImageView.ScaleType.CENTER_CROP);mini.setBackground(round(0xff35373a,6,0));mini.setClipToOutline(true);mini.setAlpha(i==viewIndex?1:.55f);mini.setContentDescription(q.name);mini.setOnClickListener(v->{viewIndex=idx;drawViewer(true);});LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(dp(i==viewIndex?48:35),dp(i==viewIndex?53:42));lp.setMargins(dp(2),0,dp(2),0);film.addView(mini,lp);Bitmap cached=thumbs.get(q,()->handler.post(()->{Bitmap th=thumbs.get(q,()->{});if(th!=null&&gen==viewerGeneration)mini.setImageBitmap(th);}));if(cached!=null)mini.setImageBitmap(cached);animateCard(mini,i-Math.max(0,viewIndex-3),animate);}
        LinearLayout actions=horizontal();actions.setPadding(dp(5),dp(4),dp(5),dp(4));actions.setBackground(round(light?0xffededf2:0xff202025,35,light?0x15000000:0x35ffffff));LinearLayout.LayoutParams act=new LinearLayout.LayoutParams(-1,dp(62));act.setMargins(dp(17),dp(4),dp(17),dp(12));wrap.addView(actions,act);Button fav=button(favorites.contains(m.uri.toString())?"Saved":"Favourite",()->{String k=m.uri.toString();if(!favorites.add(k))favorites.remove(k);saveFavorites();gallery.marks(favorites,selected,selecting);Button f=(Button)actions.getChildAt(0);f.setText(favorites.contains(k)?"Saved":"Favourite");});actionIcon(fav,R.drawable.ic_heart);actions.addView(fav,new LinearLayout.LayoutParams(0,-1,1));Button detailsAction=button("Details",()->details(m));actionIcon(detailsAction,R.drawable.ic_info);actions.addView(detailsAction,new LinearLayout.LayoutParams(0,-1,1));Button shareAction=button("Share",()->share(m));actionIcon(shareAction,R.drawable.ic_share_2);actions.addView(shareAction,new LinearLayout.LayoutParams(0,-1,1));if(animate&&motion&&ValueAnimator.areAnimatorsEnabled()){viewer.setAlpha(0);viewer.setScaleX(.96f);viewer.setScaleY(.96f);viewer.animate().alpha(1).scaleX(1).scaleY(1).setDuration(280).start();}}
    private void stepViewer(int d){int i=Math.max(0,Math.min(viewList.size()-1,viewIndex+d));if(i!=viewIndex){viewIndex=i;drawViewer(true);}}
    private void closeViewer(){if(viewer==null)return;if(video!=null){video.stopPlayback();video=null;}viewerGeneration++;FrameLayout old=viewer;viewer=null;if(motion&&ValueAnimator.areAnimatorsEnabled())old.animate().alpha(0).scaleX(.96f).scaleY(.96f).setDuration(220).withEndAction(()->root.removeView(old)).start();else root.removeView(old);if(tab==3){remember();render(false);}}
    private void details(Media m){new AlertDialog.Builder(this).setTitle("Media details").setMessage(m.name+"\n\n"+m.displayDate("d MMMM yyyy, HH:mm")+"\nAlbum: "+m.album+"\nType: "+(m.video?"Video":"Photo")).setPositiveButton("OK",null).show();}
    private void share(Media m){Intent i=new Intent(Intent.ACTION_SEND).setType(m.mime!=null?m.mime:(m.video?"video/*":"image/*")).putExtra(Intent.EXTRA_STREAM,m.uri).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);i.setClipData(ClipData.newRawUri(m.name,m.uri));startActivity(Intent.createChooser(i,"Share media"));}
    private void back(){if(viewer!=null){closeViewer();return;}if(selecting){finishSelection();return;}if(!album.isEmpty()||!query.isEmpty()){remember();album="";query="";buildHeader();render(true);return;}if(tab!=0){switchTab(0);return;}finish();}
    @Override public void onBackPressed(){back();}
    @Override public void onConfigurationChanged(Configuration c){super.onConfigurationChanged(c);root.requestApplyInsets();}
    private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}
    @Override protected void onDestroy(){handler.removeCallbacksAndMessages(null);if(observer!=null)getContentResolver().unregisterContentObserver(observer);if(video!=null)video.stopPlayback();if(gallery!=null)gallery.dispose();if(thumbs!=null)thumbs.close();if(updater!=null)updater.close();io.shutdownNow();viewerIO.shutdownNow();super.onDestroy();}
